const defaultLevels: LibraryAthleteLevel[] = ['developing', 'trained', 'advanced'];

function pathways(events: EventTag[]): EventPathway[] {
  if (events.length === 4) return ['shared'];
  const matchesShort = events.some(event => event === '60m' || event === '100m');
  const matchesLong = events.some(event => event === '200m' || event === '400m');
  return matchesShort && matchesLong ? ['short-sprint-100-200', 'long-sprint-200-400'] : matchesLong ? ['long-sprint-200-400'] : ['short-sprint-100-200'];
}

type Item = Omit<LibraryWorkoutItem, 'id'>;

type AuthoredWorkout = {
  purpose: string;
  intendedAthlete: string;
  secondaryCategories?: LibraryWorkoutCategory[];
  levels?: LibraryAthleteLevel[];
  phases?: LibrarySeasonPhase[];
  equipment?: string[];
  surface?: LibrarySurface[];
  warmup?: Item[];
  sprintWork?: Item[];
  plyometrics?: Item[];
  strength?: Item[];
  cooldown?: Item[];
  intensity: string;
  recovery: string;
  cues: string[];
  modifications: string[];
  safety: string[];
  sources: string[];
};

const commonSafety = 'Stop if pain is sharp, one-sided symptoms worsen, or mechanics change. Stop the quality set when timing or visible technique deteriorates. Return-to-sprint decisions after injury belong to a qualified clinician/coach, not the app.';
const commonCooldown = (): Item[] => [item('Easy downshift', { durationSeconds: 300, notes: '3-8 min easy walk, breathing downshift, then brief comfortable mobility. Long static stretching is optional after the session, never forced.' })];
const sprintWarmup = (): Item[] => [item('RAMP sprint warm-up', { durationSeconds: 900, notes: 'Raise: 4-6 min easy movement. Mobilize: ankle rocks, leg swings, hip circles, walking lunge. Activate: glute bridge, band walk if available, A-march/A-skip, wall-switch drill. Potentiate: 2 x 30 m build-ups (about 60%, then 75%) and 1 x 20 m at about 85%; add one event-specific rehearsal.' })];
const lowDayWarmup = (): Item[] => [item('Low-day warm-up', { durationSeconds: 600, notes: '5 min easy movement; dynamic ankle/hip mobility; marching, skipping, and two progressive strides that remain comfortably submaximal.' })];

function item(name: string, values: Partial<Item> = {}): Item {
  return {
    name,
    coachingCues: values.coachingCues ?? [],
    countsTowardSprintVolume: values.countsTowardSprintVolume ?? false,
    countsTowardHighIntensityVolume: values.countsTowardHighIntensityVolume ?? false,
    ...values,
  };
}

function sprint(name: string, sets: number, reps: number, distanceMeters: number, intensity: string, recovery: string, fastZoneMeters = 0, notes?: string): Item {
  return item(name, {
    sets, reps, distanceMeters, fastZoneMeters: fastZoneMeters || undefined,
    intensity: { basis: intensity.includes('%') ? 'percent-max-velocity' : 'technical', description: intensity },
    recovery: { description: recovery }, notes,
    countsTowardSprintVolume: true,
    countsTowardHighIntensityVolume: fastZoneMeters > 0,
  });
}

function section(id: string, label: string, recordId: string, entries: Item[] = []) {
  return { id, label, items: entries.map((entry, index) => ({ ...entry, id: `${recordId.toLowerCase()}-${id}-${index + 1}` })) };
}

