function makeWorkout(entry: CatalogEntry): LibraryWorkout {
  const now = '2026-07-24T00:00:00.000Z';
  const details = authored[entry.id];
  if (!details) throw new Error(`Missing authored library content for ${entry.id}`);
  const highCns = !['tempo-recovery', 'strength'].includes(entry.category) && entry.status === 'approved';
  return {
    id: entry.id, slug: entry.id.toLowerCase(), name: entry.name,
    purpose: details.purpose, intendedAthlete: details.intendedAthlete, primaryCategory: entry.category,
    secondaryCategories: details.secondaryCategories ?? [], eventPathways: pathways(entry.events), eventTags: entry.events,
    athleteLevels: details.levels ?? entry.levels ?? defaultLevels,
    seasonPhases: details.phases ?? entry.phases ?? categoryPhases[entry.category],
    specialistProfiles: ['unclassified', 'balanced'], equipmentRequired: details.equipment ?? entry.equipment ?? categoryEquipment[entry.category], equipmentOptional: [],
    surface: { required: details.surface ?? entry.surfaces ?? categorySurfaces[entry.category], preferred: [], prohibited: [], notes: 'Use a safe, inspected surface that matches the session requirement.' },
    sections: {
      warmup: section('warmup', 'Warm-up', entry.id, details.warmup ?? sprintWarmup()),
      sprintWork: section('sprint-work', 'Sprint work', entry.id, details.sprintWork),
      plyometrics: section('plyometrics', 'Plyometrics', entry.id, details.plyometrics),
      strength: section('strength', 'Strength', entry.id, details.strength),
      cooldown: section('cooldown', 'Cooldown', entry.id, details.cooldown ?? commonCooldown()),
    },
    intensitySummary: details.intensity, recoverySummary: details.recovery,
    metrics: { totalSprintVolumeMeters: entry.totalVolume, highIntensitySprintVolumeMeters: entry.highIntensityVolume, estimatedDurationMinutes: entry.duration, highCns, metabolicDemand: entry.category === 'special-endurance' ? 'very-high' : highCns ? 'high' : entry.category === 'tempo-recovery' ? 'low' : 'moderate' },
    coachingCues: details.cues, modifications: details.modifications,
    safetyNotes: ['Training organization only; this is not injury diagnosis or return-to-play clearance.', ...details.safety],
    sourceNotes: details.sources.map(sourceId => ({ sourceId, note: `Authored ${entry.id} library record.` })),
    familyId: entry.category, progressionLevel: (details.levels ?? entry.levels)?.includes('advanced') ? 4 : (details.levels ?? entry.levels)?.includes('trained') ? 3 : (details.levels ?? entry.levels)?.includes('developing') ? 2 : 1,
    version: 1, approvalStatus: entry.status, createdAt: now, updatedAt: now, archivedAt: entry.status === 'archived' ? now : undefined,
  };
}

export const starterWorkoutLibrary = catalog.map(makeWorkout);
export const starterCatalogCounts = { approved: starterWorkoutLibrary.filter(item => item.approvalStatus === 'approved').length, draft: starterWorkoutLibrary.filter(item => item.approvalStatus === 'draft').length, archived: starterWorkoutLibrary.filter(item => item.approvalStatus === 'archived').length };
